mapper.update:
UPDATE REPLIES
   SET CONTENT = #{modifyReplyVO.content}
     , MDFY_DT = SYSDATE
     , FILE_SET_ID = #{modifyReplyVO.fileSetId}
 WHERE ARTICLE_ID = #{articleId}
   AND ID = #{replyId}
   AND EMAIL = #{modifyReplyVO.email}
   AND DEL_YN = 'N'

UPDATE REPLIES
   SET DEL_YN = 'Y'
     , MDFY_DT = SYSDATE
 WHERE ARTICLE_ID = #{articleId}
   AND ID = #{replyId}
   AND DEL_YN = 'N'

UPDATE REPLIES
   SET RECOMMEND_CNT = RECOMMEND_CNT + 1
 WHERE ARTICLE_ID = #{articleId}
   AND ID = #{replyId}
   AND DEL_YN = 'N'

mapper.select:
SELECT RECOMMEND_CNT 
  FROM REPLIES
 WHERE ARTICLE_ID = #{articleId}
   AND ID = #{replyId}
   AND DEL_YN = 'N'
